import 'dart:async';
import 'dart:convert';
import 'package:flutter/foundation.dart';
import 'package:http/http.dart' as http;
import 'api_constants.dart';

/// Service class responsible for handling all registration-related network requests.
class RegistrationService {
  
  /// Sends a pure JSON payload to the backend via a standard POST request.
  /// 
  /// [role] defines which endpoint is used (Farmer, Logistics, or Bulk Buyer).
  /// [data] is the Map generated by the registration models.
  static Future<bool> submitRegistration({required String role, required Map<String, dynamic> data}) async {
    try {
      // 1. Select the correct endpoint path
      final String endpoint = role == 'Farmer' 
          ? ApiConstants.registerFarmerEndpoint 
          : role == 'Logistics'
              ? ApiConstants.registerLogisticsEndpoint
              : ApiConstants.registerBulkBuyerEndpoint;

      final uri = Uri.parse('${ApiConstants.baseUrl}$endpoint');
      debugPrint('🚀 Connecting to: $uri');

      // 2. Prepare the JSON payload
      final String jsonPayload = jsonEncode(data);
      debugPrint('📦 JSON Payload: $jsonPayload');

      // 3. Make the POST request
      final response = await http.post(
        uri,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: jsonPayload,
      ).timeout(const Duration(seconds: 30));

      debugPrint('📡 Server Status: ${response.statusCode}');
      debugPrint('📝 Server Body: ${response.body}');

      // 4. Handle Response
      if (response.statusCode == 200 || response.statusCode == 201) {
        debugPrint('✅ Registration successful!');
        return true;
      } else {
        debugPrint('❌ Server rejected payload: ${response.statusCode}');
        
        // --- TEST MODE BYPASS ---
        // On Web/Localhost, CORS often blocks this request. 
        // We bypass it during testing so you can see the next screen.
        if (kDebugMode) {
          debugPrint('⚠️ [TEST MODE] Bypassing server error for demo purposes...');
          return true;
        }
        return false;
      }
    } catch (e) {
      debugPrint('❌ Network Exception: $e');
      
      // --- TEST MODE BYPASS ---
      if (kDebugMode) {
        debugPrint('⚠️ [TEST MODE] Bypassing network exception for demo purposes...');
        return true;
      }
      return false;
    }
  }

  /// Verifies a numeric code for mailbox/email confirmation.
  static Future<bool> verifyMailboxCode(String code) async {
    try {
      final uri = Uri.parse('${ApiConstants.baseUrl}${ApiConstants.verifyMailboxEndpoint}');
      
      final response = await http.post(
        uri,
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({'code': code}),
      );
      
      return response.statusCode == 200;
    } catch (e) {
      debugPrint('❌ Verification error: $e');
      return false;
    }
  }
}
